#include <map>
#include <iostream>

int main() {
    std::map<int, char> m = {{1, 'a'}, {5, 'e'}, {10, 'j'}};

    // O(log N) search for key 5
    auto pos = m.find(5);
    if (pos != m.end()) {
        std::cout << "Found key: " << pos->first << " (O(log N))\n";
    }

    // O(log N) boundary search
    auto low = m.lower_bound(6);
    // low points to {10, 'j'} because 10 is the first key >= 6
    if (low != m.end()) {
        std::cout << "Lower bound for 6 is: " << low->first << "\n";
    }
    return 0;
}
